typedef struct _KEYBOARD_INPUT_DATA {
  USHORT UnitId;
  USHORT MakeCode;
  USHORT Flags;
  USHORT Reserved;
  ULONG ExtraInformation;
} KEYBOARD_INPUT_DATA, *PKEYBOARD_INPUT_DATA;

typedef struct _KEYBOARD_EXTENDED_ATTRIBUTES {   UCHAR Version;
UCHAR FormFactor;   UCHAR KeyType;
UCHAR PhysicalLayout;
UCHAR VendorSpecificPhysicalLayout;   UCHAR IETFLanguageTagIndex;
UCHAR ImplementedInputAssistControls;
} KEYBOARD_EXTENDED_ATTRIBUTES, *PKEYBOARD_EXTENDED_ATTRIBUTES;

typedef struct _KEYBOARD_INDICATOR_PARAMETERS {
USHORT UnitId;   USHORT LedFlags;
} KEYBOARD_INDICATOR_PARAMETERS, *PKEYBOARD_INDICATOR_PARAMETERS;

typedef struct _KEYBOARD_TYPEMATIC_PARAMETERS {
USHORT UnitId;   USHORT Rate;   USHORT Delay;
} KEYBOARD_TYPEMATIC_PARAMETERS, *PKEYBOARD_TYPEMATIC_PARAMETERS;

typedef struct _MOUSE_INPUT_DATA {
USHORT UnitId;   USHORT Flags;   union {
ULONG Buttons;     struct {
USHORT ButtonFlags;       USHORT ButtonData;
};   };
ULONG  RawButtons;
LONG   LastX;   LONG   LastY;
ULONG  ExtraInformation;
} MOUSE_INPUT_DATA, *PMOUSE_INPUT_DATA;

HRESULT GetEffectStatus(
